/** The eight newspapers (DC's Super Heroes), keyed by paper key. */
function dc_papers() {
  static $papers = null;
  if ($papers !== null) return $papers;
  $papers = [
    'globe' => ['key' => 'globe', 'name' => 'The Washington Globe', 'dc_super_hero' => 'Hawkman', 'leans' => 'Political', 'ability' => 'Your Political influence counts toward any candidate.', 'flavor' => 'Francis Blair\'s Globe, the party organ of the Jackson men: the line came from the White House.'],
    'argus' => ['key' => 'argus', 'name' => 'The Albany Argus', 'dc_super_hero' => 'Red Tornado', 'leans' => 'Political', 'ability' => 'Each election you win is worth +1 prestige at the end of the game.', 'flavor' => 'The voice of the Albany Regency, Van Buren\'s machine. It could elect anyone the party named.'],
    'intelligencer' => ['key' => 'intelligencer', 'name' => 'The National Intelligencer', 'dc_super_hero' => 'Booster Gold', 'leans' => 'Political', 'ability' => 'You never gain Scandals: when a negative story would give you one, ignore it.', 'flavor' => 'Gales and Seaton\'s paper of record, printing the debates of Congress. Too dull to smear.'],
    'journal' => ['key' => 'journal', 'name' => 'The Journal of Commerce', 'dc_super_hero' => 'Nightwing', 'leans' => 'Economic', 'ability' => 'Your first and second Economic stories each turn give +1 influence each.', 'flavor' => 'Prices current, ship arrivals and the money market, for the merchants of New York.'],
    'herald' => ['key' => 'herald', 'name' => 'The New York Herald', 'dc_super_hero' => 'Shazam!', 'leans' => 'Economic', 'ability' => 'Once each turn, you may pay 2 influence to set aside the top story of the main deck; it joins your next hand.', 'flavor' => 'James Gordon Bennett\'s Herald: first with the news, by any means, at any cost.'],
    'sun' => ['key' => 'sun', 'name' => 'The Sun', 'dc_super_hero' => 'Batgirl', 'leans' => 'Social', 'ability' => 'Once each turn, you may discard a Scandal from your hand to draw three cards.', 'flavor' => 'Benjamin Day\'s Sun, a penny a copy: police court, murders, and the moon men.'],
    'north_star' => ['key' => 'north_star', 'name' => 'The North Star', 'dc_super_hero' => 'Starfire', 'leans' => 'Social', 'ability' => 'Once each turn, if you play two or more Social stories, draw a card.', 'flavor' => 'Frederick Douglass\'s weekly from Rochester: "Right is of no sex - Truth is of no color."'],
    'aurora' => ['key' => 'aurora', 'name' => 'The Aurora', 'dc_super_hero' => 'Black Canary', 'leans' => 'Negative', 'ability' => '+1 influence for each different negative story you play.', 'flavor' => 'Benjamin Franklin Bache\'s Aurora, which called Washington a tyrant and Adams worse.'],
  ];
